        num_clauses = random.randint(5, 10)
        clauses = []
        for _ in range(num_clauses):
            clause = [random.choice([1, -1]) * (i + 1) for i in range(n)]
            clauses.append(clause)
        return clauses

    def compute_nerve(clauses):
        n = len(clauses[0])
        nerve = [[False] * n for _ in range(n)]
        for clause in clauses:
            for i in range(n):
                if clause[i] > 0:
                    for j in range(i + 1, n):
                        if clause[j] > 0 and (nerve[i][j] or nerve[j][i]):
                            return None
                        nerve[i][j] = True
                        nerve[j][i] = True
        return nerve

    def compute_local_indeterminacy(nerve):
        if not nerve:
            return float('inf')
        n = len(nerve)
        indeterminacy = 0
        for i in range(n):
            for j in range(i + 1, n):
                if nerve[i][j]:
                    indeterminacy += 1
        return indeterminacy

    def estimate_complexity(clauses):
        return len(clauses)

    n_max = 40
    instances_tested = 30
    total_indeterminacy = 0
    total_complexity = 0

    for _ in range(instances_tested):
